/// The stored level of the preset at `path` (relative to `presets/factory`).
pub(super) fn stored(path: &str) -> Option<StoredLevel> {
    LEVELS
        .iter()
        .find(|(p, _, _)| *p == path)
        .map(|&(_, try_index, output)| StoredLevel { try_index, output })
}

