/// The stored level (dB) of the pad on `key` of the kit at `path`.
pub(super) fn stored_pad(path: &str, key: u8) -> Option<f32> {
    PAD_LEVELS
        .iter()
        .find(|(p, k, _)| *p == path && *k == key)
        .map(|&(_, _, level)| level)
}
